# -*- coding: utf-8 -*-
from common import md, esc, cq, wq
T=[("d1","🔺","三一神与基督的位格","书信是三一神论与基督论的根据：救恩由父拣选、子救赎、灵印记（{{弗1:3-14}}）；子“本有神的形像”（{{腓2:6}}），“神本性一切的丰盛都有形有体地居住在基督里面”（{{西2:9}}），是“神荣耀所发的光辉，是神本体的真像”（{{来1:3}}）。",
    "弗1:3-14；林后13:14；腓2:5-11；西1:15-20；来1:1-4；多2:13；约壹4:2-3",[("bc",9,"同样，保罗问安时也说：“愿主耶稣的恩惠、神的慈爱、圣灵的感动，常与你们众人同在。”（林后13:14）这几处经文都充分教导我们，在神的独一本质中有三个不同的位格。")],None),
  ("d2","📖","圣经的默示与充足","“圣经都是神所默示的”（{{提后3:16}}）；“预言从来没有出于人意的”（{{彼后1:21}}）；彼得把保罗书信与“别的经书”并列（{{彼后3:16}}）。","提后3:15-17；彼后1:19-21；3:15-16；帖前2:13；加1:8",[("bc",3,"我们承认神的话语不是出于人意，而是如使徒彼得所说的，人被圣灵感动说出神的话来（彼后1:21）。"),("bc",7,"因此，任何人教导有悖于圣经的道理都是不合法的，即便是使徒，或（如使徒保罗所说）天上来的使者也不例外（参见加1:8）。")],('wcf',1,6,"因此，无论以「圣灵新启示」的名义，还是人的传统为借口都不能对《圣经》再添加任何新内容。")),
  ("d3","🌑","罪与人的败坏","“世人都犯了罪，亏缺了神的荣耀”（{{罗3:23}}）；“你们死在过犯罪恶之中”（{{弗2:1}}）；罪从一人入了世界（{{罗5:12}}）。","罗1:18–3:20；5:12-21；弗2:1-3；4:17-19；多3:3",[("bc",15,"我们相信由于亚当的悖逆，原罪已传遍全人类。它使人性全然败坏，它还具有遗传性，因而所有人都受其污染，甚至母腹中的婴孩也不例外。"),("dort",3,12,"归信就是重生，是成为新造的人，是从死里复活。")],None),
  ("d4","⚖️","因信称义","称义是神的法庭宣告：罪得赦免、基督的义归算给信的人（{{罗3:24-26}}；{{林后5:21}}；{{腓3:9}}）。信心是接受基督的工具，不是功德。","罗3:21–5:21；加2:15-21；3:6-14；腓3:7-11；多3:4-7",[("hc",60),("hc",61),("bc",23,"我们相信，我们蒙福在于，因耶稣基督的缘故我们的罪得了赦免，就在神面前得称为义，正如大卫与保罗所教导我们的：那在行为以外蒙神算为义的人是有福的（罗4:6；诗32:1）。")],('wcf',11,1,"一、对那些蒙了有效地呼召的人，神也白白地称他们为义。")),
  ("d5","🌱","成圣与善行","称义与成圣不可分也不可混：在基督里的人“是新造的人”（{{林后5:17}}）；“我们原是祂的工作，在基督耶稣里造成的，为要叫我们行善”（{{弗2:10}}）；“没有行为的信心是死的”（{{雅2:26}}）。","罗6–8；加5:16-26；弗4:17–5:21；西3:1-17；雅2:14-26；彼前1:13-25",[("hc",86),("bc",24,"然而，这些善行并不是我们称义的资本，因为在我们还未行任何善事之前，我们就因信基督而得称为义了。")],('wsc',35)),
  ("d6","🌷","拣选与保守","“神从创立世界以前，在基督里拣选了我们”（{{弗1:4}}）；“预先所定下的人又召他们来……又叫他们得荣耀”（{{罗8:30}}）；“那在你们心里动了善工的，必成全这工”（{{腓1:6}}）。","罗8:28-39；9–11；弗1:3-14；帖后2:13-14；提后1:9；2:19；彼前1:1-5；犹24",[("bc",16),("dort",1,7,"拣选是神不变的旨意。"),("dort",5,8)],('wcf',17,1)),
  ("d7","💧","恩典之约与圣礼","洗礼取代割礼作为立约的记号（{{西2:11-12}}）；圣餐是“新约”的杯（{{林前11:25}}）；信徒的儿女是“圣洁的”（{{林前7:14}}）。","罗4:11；林前10:1-4,16-17；11:23-32；加3:27-29；西2:11-12；彼前3:20-21",[("hc",74),("bc",34,"他废除了与血有关的割礼，并设立圣洗礼取代了它；藉着洗礼，我们归入神的教会，从不信之人和假信仰中被分别出来，身上带着他的标志和印记，完全将自己交托与他。")],('wcf',28,4)),
  ("d8","⛪","教会、职分与纪律","教会是基督的身体（{{林前12:27}}）、神的家（{{提前3:15}}）、圣灵的殿（{{弗2:21-22}}）；长老、执事按圣经资格设立（{{提前3:1-13}}；{{多1:5-9}}）；纪律是为挽回（{{林前5:5}}）。","林前5；12–14；弗4:1-16；提前3；多1；彼前5:1-4；约叁9-10",[("hc",54),("bc",27,"我们相信并宣告圣而公之基督教会，或称普世教会或大公教会。她是真信徒的圣会。"),("bc",30,"教会须有牧师传讲神的道，并执行圣礼；还须有长老和执事，他们要与牧师一同组成教会议会。")],('wcf',25,1)),
  ("d9","🏛️","国家、社会与家庭","“在上有权柄的，人人当顺服他”（{{罗13:1}}）；为君王代祷（{{提前2:1-2}}）；“敬畏神，尊敬君王”（{{彼前2:17}}）；家规在主里改造社会关系。","罗13:1-7；提前2:1-4；多3:1-2；彼前2:13–3:7；弗5:21–6:9；西3:18–4:1；门",[("bc",36,"此外，每个人，无论他是什么身份、地位，处于何种境遇，都当顺服执政掌权的，向他们纳税，尊敬他们，并在不违反圣经的一切事上顺服他们。")],None),
  ("d10","🌅","末世与盼望","基督复活是初熟的果子（{{林前15:20}}）；主必亲自从天降临（{{帖前4:16}}）；“我们照祂的应许，盼望新天新地”（{{彼后3:13}}）。","林前15；林后5:1-10；帖前4:13–5:11；帖后1–2；彼后3；来12:22-29",[("bc",37,"最后，我们相信，正如圣经所说的，当主所定的那日子、那时辰来到时——那日子、那时辰无人知道，当被选的人数添满时，我们的主耶稣基督将在大荣耀和威严中，有形有体地从天降临，正如他升天时那样（徒1:11）。"),("hc",45)],None)]
def build():
    b=['<div class="dmap glass reveal"><div class="dm-c">📨 书信教义<br><small>十大主题</small></div><div class="dm-r">'+"".join(f'<a href="#{i}" class="dm-n" style="--i:{k}">{ic} {t}</a>' for k,(i,ic,t,*_) in enumerate(T))+'</div></div>']
    for i,ic,t,s,refs,qs,w in T:
        b.append(f'<h2 id="{i}">{ic} {t}</h2>')
        b.append(f'<h3 id="{i}-txt">经文要义</h3><div class="card glass"><p>{md(s)}</p><p class="refs">📨 主要经文：{esc(refs)}</p></div>')
        b.append(f'<h3 id="{i}-cf">信条对照</h3><div class="confs">'+"".join(cq(q) for q in qs)+(wq(w[0],*w[1:]) if w and w[0]=='wcf' else (wq(w[0],w[1]) if w else ""))+'</div>')
    b.append('<h2 id="dw">📙 三项联合信条 vs 威斯敏斯特标准：侧重比较</h2>')
    R=[("圣约结构","在洗礼、儿女、拣选中运用圣约语言；未单列“行为之约”","第 7 章明确区分行为之约与恩典之约"),("风格","海德堡：个人、敬拜性（“我唯一的安慰”）","系统、精确、逻辑性强"),("结构","HC：罪—救—恩（像罗马书）","从圣经、神论到末世的系统次序"),
       ("拣选的表述","多特：牧养性（确据、安慰）","第 3 章：预旨的完整论述"),("安息日","HC 103：敬拜与安息的属灵意义","第 21 章：主日为基督徒的安息日"),("教会政体","BC 30–32：牧师、长老、执事组成议会","长老会体制，区会、大会")]
    b.append('<div class="tbl"><table><thead><tr><th>主题</th><th>三项联合信条（欧陆）</th><th>威斯敏斯特标准（长老会）</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{d}</td></tr>' for a,c,d in R)+'</tbody></table></div><p class="note">两者在教义实质上一致（同属改革宗正统），差异主要在表述侧重与历史处境。北美的 URCNA、CanRC、HRC、PRC 采用三项联合信条；OPC 采用威斯敏斯特标准。</p>')
    return "".join(b)
